/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: retitled, mount, number
 *   Constants: inputs
 * Tests
 *   - with every original number empty, one note says so and the inputs show the proposal, which the table reports with the draft it shows
 *   - a stored number adds the original numbers in text, marks each filled cell, and a number typed over a stored one is marked as replacing it, the original struck through
 *   - titles that stop the proposal are listed with their reasons and marked on their rows, and nothing is proposed or cleaned
 *   - titles giving Track Numbers alone are proposed, marked for checking and not said to be included in the update
 *   - the optional cleanup, off by default, previews each cleaned title and chooses it, never touches a title the administrator edited, and turning it off restores the others
 *   - a title the administrator typed equal to the cleaned text survives turning the cleanup on and off
 *   - a 44-track Album on three discs sums up the proposal and folds its uniform rows per disc, with edited and flagged rows open first and folded inputs keeping their values
 *   - on a 44-track Album the cleanup's titles keep the uniform rows folded per disc, while a title typed otherwise opens its row
 *   - an edit that moves its row out of a folded disc keeps the focus on the same input
 *   - a disabled table disables its inputs and the cleanup
 * @end-catalog */

import { useState } from 'react';
import { cleanup, fireEvent, render, screen, within } from '@testing-library/react';
import type { CatalogReview } from './catalogReviewApi';
import type { ReviewEditorView, ReviewEdits } from './catalogReviewEdits';
import { slotId, slotTwo } from './catalogReviewFixtures.testSupport';
import { longAlbumDiscs, longAlbumReview, pairingReview } from './catalogReviewLookupFixtures.testSupport';
import { CatalogReviewProposalTable } from './CatalogReviewProposalTable';

/**
 * The review page's table of numbers proposed from the captured titles, without the page: the original numbers or the one note
 * that they are empty, the fill and replace markers, the rows that stop the proposal, Track Numbers alone marked for checking,
 * the optional title cleanup, a 44-track Album on three discs folded per disc with its exceptions open, and the focus kept on an
 * input whose row moves. Every name is synthetic.
 */

afterEach(cleanup);

/** `item` with each member's captured and draft title replaced by `titles`. */
const retitled = (item: CatalogReview, titles: readonly string[]): CatalogReview => ({ ...item,
  source: { ...item.source, tracks: item.source.tracks.map((track, index) => ({ ...track, title: titles[index] })) },
  draft: { ...item.draft, tracks: item.draft.tracks.map((track, index) => ({ ...track, title: titles[index] })) } });
/**
 * Mounts the table over `item`'s saved draft with editing state of its own, as the page keeps it (the edits and the slots whose
 * titles the cleanup wrote), and records what it reports.
 */
function mount(item: CatalogReview, initial: ReviewEdits = {}, disabled = false) {
  const onView = vi.fn<(view: ReviewEditorView) => void>(), onCleanup = vi.fn<(keys: string[]) => void>();
  function Harness() {
    const [edits, setEdits] = useState(initial), [cleaned, setCleaned] = useState<string[]>([]);
    return <CatalogReviewProposalTable item={item} base={item.draft} edits={edits} cleaned={cleaned} disabled={disabled} onView={onView} onEdit={next => setEdits(next)}
      onCleanup={(next, _draft, keys, slots) => { onCleanup(keys); setEdits(next); setCleaned(slots); }} />;
  }
  render(<Harness />);
  return { onView, onCleanup, view: () => onView.mock.lastCall![0], table: () => screen.getByRole('region', { name: 'Check the suggested changes' }) };
}
const number = (name: string) => (screen.getByRole('spinbutton', { name }) as HTMLInputElement).value;
const inputs = ['Disc number of track 1', 'Track number of track 1', 'Disc number of track 2', 'Track number of track 2'];

test('with every original number empty, one note says so and the inputs show the proposal, which the table reports with the draft it shows', () => {
  const { table, view } = mount(pairingReview());
  expect(inputs.map(number)).toEqual(['1', '1', '1', '2']);
  expect(within(table()).getByText('Every original number is empty; these are proposed from the titles.')).toBeVisible();
  expect(within(table()).getByText('The numbers proposed from the track titles are included in this update; check them, or adjust the range.')).toBeVisible();
  expect(within(table()).queryByText(/^Original:/)).not.toBeInTheDocument();
  expect(within(table()).queryByText('Fills')).not.toBeInTheDocument();
  expect(view().numbers).toEqual({ [slotId]: { discNumber: 1, trackNumber: 1 }, [slotTwo]: { discNumber: 1, trackNumber: 2 } });
  expect(view().shown.tracks.map(track => [track.discNumber, track.trackNumber])).toEqual([[1, 1], [1, 2]]);
  expect(view().proposed.numbers.get(`track:${slotTwo}:trackNumber`)).toBe(2);
  // No captured title starts with a position: there is nothing to propose and no table, but the view is still reported.
  cleanup();
  const plain = mount(retitled(pairingReview(), ['Synthetic opening', 'Synthetic second song']));
  expect(screen.queryByRole('region', { name: 'Check the suggested changes' })).not.toBeInTheDocument();
  expect(plain.view().numbers).toEqual({ [slotId]: {}, [slotTwo]: {} });
});

test('a stored number adds the original numbers in text, marks each filled cell, and a number typed over a stored one is marked as replacing it, the original struck through', () => {
  const item = pairingReview(); item.source.tracks[1].trackNumber = 2; item.draft.tracks[1].trackNumber = 2;
  const { table, view } = mount(item);
  expect(within(table()).getAllByText(/^Original:/).map(line => line.textContent)).toEqual(['Original: — / —', 'Original: — / 2']);
  expect(within(table()).getAllByText('Fills')).toHaveLength(3);
  expect(within(table()).queryByText('Every original number is empty; these are proposed from the titles.')).not.toBeInTheDocument();
  expect(view().numbers[slotTwo]).toEqual({ discNumber: 1 });
  fireEvent.change(screen.getByRole('spinbutton', { name: 'Track number of track 2' }), { target: { value: '4' } });
  const marker = within(table()).getByText('Replaces');
  expect(marker.querySelector('s')).toHaveTextContent('2');
  // The input's own name leaves the marks out, so they describe it: the replacement with the value it replaces, or the fill.
  expect(screen.getByRole('spinbutton', { name: 'Track number of track 2' })).toHaveAccessibleDescription(/^Replaces\s*2$/);
  expect(screen.getByRole('spinbutton', { name: 'Disc number of track 2' })).toHaveAccessibleDescription('Fills');
  expect(view().shown.tracks[1].trackNumber).toBe(4);
  expect(view().edits).toEqual({ album: undefined, tracks: { [slotTwo]: { trackNumber: 4 } } });
});

test('titles that stop the proposal are listed with their reasons and marked on their rows, and nothing is proposed or cleaned', () => {
  const cases: [string[], string][] = [
    [['01 Synthetic intro', '1999 Synthetic year'], '2 · 1999 Synthetic year · its title starts with no position'],
    [['1-01 Synthetic intro', 'Disc2-03 Synthetic song'], '2 · Disc2-03 Synthetic song · its title starts with no position'],
    [['1-01 Synthetic intro', '1-01 Synthetic repeat'], '2 · 1-01 Synthetic repeat · another track\'s title gives the same position'],
    [['1-01 Synthetic intro', '02 Synthetic song'], '2 · 02 Synthetic song · its position is written unlike the others']
  ];
  for (const [titles, line] of cases) {
    const { table, view } = mount(retitled(pairingReview(), titles));
    expect(within(table()).getByText('Nothing was proposed from the titles because of these tracks:')).toBeVisible();
    expect(within(table()).getByText(line)).toBeVisible();
    // The reason is also a text marker on the row itself.
    expect(within(table()).getAllByText(line.split(' · ').at(-1)!)).toHaveLength(1);
    expect(inputs.map(number)).toEqual(['', '', '', '']);
    expect(view().numbers).toEqual({ [slotId]: {}, [slotTwo]: {} });
    expect(screen.queryByRole('checkbox')).not.toBeInTheDocument();
    cleanup();
  }
  // A stored number that disagrees with its title stops it too.
  const disagreeing = pairingReview(); disagreeing.source.tracks[1].trackNumber = 7; disagreeing.draft.tracks[1].trackNumber = 7;
  const { table } = mount(disagreeing);
  expect(within(table()).getByText('2 · 1-02 Synthetic second song (Live) · its Disc or Track Number differs from its title')).toBeVisible();
  expect(inputs.map(number)).toEqual(['', '', '', '7']);
});

test('titles giving Track Numbers alone are proposed, marked for checking and not said to be included in the update', () => {
  const { table, view } = mount(retitled(pairingReview(), ['01 - Synthetic overture', '02 - Synthetic song']));
  expect(inputs.map(number)).toEqual(['', '1', '', '2']);
  expect(within(table()).getAllByText('Track Number read from the title only; please check')).toHaveLength(2);
  // The row's note describes its input.
  expect(screen.getByRole('spinbutton', { name: 'Track number of track 2' })).toHaveAccessibleDescription('Track Number read from the title only; please check');
  expect(within(table()).queryByText(/are included in this update/)).not.toBeInTheDocument();
  // They are not preselected: the Update selection defaults carry no number for them.
  expect(view().proposed.numbers.size).toBe(0);
  // A number typed over one is the administrator's own, no longer marked.
  fireEvent.change(screen.getByRole('spinbutton', { name: 'Track number of track 2' }), { target: { value: '2' } });
  fireEvent.change(screen.getByRole('spinbutton', { name: 'Track number of track 2' }), { target: { value: '3' } });
  expect(within(table()).getAllByText('Track Number read from the title only; please check')).toHaveLength(1);
  expect(screen.getByRole('spinbutton', { name: 'Track number of track 2' })).not.toHaveAttribute('aria-describedby');
});

test('the optional cleanup, off by default, previews each cleaned title and chooses it, never touches a title the administrator edited, and turning it off restores the others', () => {
  const { table, view, onCleanup } = mount(pairingReview(), { tracks: { [slotId]: { title: 'My own synthetic title' } } });
  const toggle = within(table()).getByRole('checkbox', { name: 'Also remove the position from the track titles (optional)' });
  expect(toggle).not.toBeChecked();
  expect(within(table()).getByText('→ My own synthetic title')).toBeVisible();
  expect(within(table()).queryByText('→ Synthetic second song (Live)')).not.toBeInTheDocument();
  fireEvent.click(toggle);
  expect(onCleanup).toHaveBeenLastCalledWith([`track:${slotTwo}:title`]);
  expect(toggle).toBeChecked();
  expect(within(table()).getByText('→ Synthetic second song (Live)')).toBeVisible();
  expect(within(table()).getByText('→ My own synthetic title')).toBeVisible();
  expect(view().shown.tracks.map(track => track.title)).toEqual(['My own synthetic title', 'Synthetic second song (Live)']);
  fireEvent.click(toggle);
  expect(onCleanup).toHaveBeenLastCalledWith([]);
  expect(toggle).not.toBeChecked();
  expect(within(table()).queryByText('→ Synthetic second song (Live)')).not.toBeInTheDocument();
  expect(view().shown.tracks.map(track => track.title)).toEqual(['My own synthetic title', '1-02 Synthetic second song (Live)']);
  cleanup();
  // Titles saved cleaned show it checked; turning it off restores the captured titles, as edits of the saved ones.
  const saved = pairingReview(); saved.draft.tracks = saved.draft.tracks.map(track => ({ ...track, title: track.title.slice(5) }));
  const again = mount(saved);
  const box = within(again.table()).getByRole('checkbox', { name: 'Also remove the position from the track titles (optional)' });
  expect(box).toBeChecked();
  fireEvent.click(box);
  expect(again.view().edits.tracks).toEqual({ [slotId]: { title: '1-01 Synthetic opening (Live)' }, [slotTwo]: { title: '1-02 Synthetic second song (Live)' } });
});

test('a title the administrator typed equal to the cleaned text survives turning the cleanup on and off', () => {
  const { table, view } = mount(pairingReview(), { tracks: { [slotTwo]: { title: 'Synthetic second song (Live)' } } });
  const toggle = within(table()).getByRole('checkbox', { name: 'Also remove the position from the track titles (optional)' });
  expect(toggle).not.toBeChecked();
  fireEvent.click(toggle);
  expect(toggle).toBeChecked();
  expect(view().shown.tracks.map(track => track.title)).toEqual(['Synthetic opening (Live)', 'Synthetic second song (Live)']);
  // Off restores only the title the cleanup wrote; the typed one stays the administrator's edit.
  fireEvent.click(toggle);
  expect(toggle).not.toBeChecked();
  expect(view().edits.tracks).toEqual({ [slotId]: {}, [slotTwo]: { title: 'Synthetic second song (Live)' } });
  expect(view().shown.tracks.map(track => track.title)).toEqual(['1-01 Synthetic opening (Live)', 'Synthetic second song (Live)']);
});

test('a 44-track Album on three discs sums up the proposal and folds its uniform rows per disc, with edited and flagged rows open first and folded inputs keeping their values', () => {
  const item = longAlbumReview(), slot = (position: number) => item.source.tracks[position - 1].slotId;
  const { table, view } = mount(item, { tracks: { [slot(20)]: { trackNumber: 7 } } });
  expect(within(table()).getByText('44 tracks · 3 discs · Numbers from the titles (1.01 to 3.14)')).toBeVisible();
  // The edited row stays open, before the three disc disclosures.
  const open = table().querySelector('fieldset > ol')!;
  expect(within(open as HTMLElement).getAllByRole('listitem').map(row => row.querySelector('strong')!.textContent)).toEqual(['20 · 2.05.Synthetic long song 20']);
  const folds = [...table().querySelectorAll('details')];
  expect(folds.map(fold => fold.querySelector('summary')!.textContent)).toEqual(['Disc 1 · 15 tracks', 'Disc 2 · 14 tracks', 'Disc 3 · 14 tracks']);
  expect(folds.every(fold => !fold.open)).toBe(true);
  expect(longAlbumDiscs).toEqual([15, 15, 14]);
  // Folded rows stay mounted with their proposed values.
  expect(number('Track number of track 44')).toBe('14');
  expect(number('Disc number of track 44')).toBe('3');
  expect(view().numbers[slot(44)]).toEqual({ discNumber: 3, trackNumber: 14 });
  cleanup();
  // One mistyped title stops the whole proposal: only its row is listed and open, the others fold.
  const mistyped = longAlbumReview(); mistyped.source.tracks[30].title = 'Synthetic long song 31'; mistyped.draft.tracks[30].title = 'Synthetic long song 31';
  const stopped = mount(mistyped);
  expect(within(stopped.table()).getByText('31 · Synthetic long song 31 · its title starts with no position')).toBeVisible();
  expect(within(stopped.table()).getByText('44 tracks · 3 discs')).toBeVisible();
  const openRows = stopped.table().querySelector('fieldset > ol')!;
  expect(within(openRows as HTMLElement).getAllByRole('listitem')).toHaveLength(1);
});

test('on a 44-track Album the cleanup\'s titles keep the uniform rows folded per disc, while a title typed otherwise opens its row', () => {
  const item = longAlbumReview(), slot = (position: number) => item.source.tracks[position - 1].slotId;
  const { table, view } = mount(item, { tracks: { [slot(7)]: { title: 'My own synthetic long song' } } });
  fireEvent.click(within(table()).getByRole('checkbox', { name: 'Also remove the position from the track titles (optional)' }));
  expect(view().shown.tracks[43].title).toBe('Synthetic long song 44');
  const open = table().querySelector('fieldset > ol')!;
  expect(within(open as HTMLElement).getAllByRole('listitem').map(row => row.querySelector('strong')!.textContent)).toEqual(['7 · 1.07.Synthetic long song 7']);
  expect([...table().querySelectorAll('details')].map(fold => fold.querySelector('summary')!.textContent))
    .toEqual(['Disc 1 · 14 tracks', 'Disc 2 · 15 tracks', 'Disc 3 · 14 tracks']);
});

test('an edit that moves its row out of a folded disc keeps the focus on the same input', () => {
  const item = longAlbumReview();
  mount(item);
  const input = screen.getByRole('spinbutton', { name: 'Track number of track 3' });
  expect(input.closest('details')).not.toBeNull();
  input.focus();
  fireEvent.change(input, { target: { value: '9' } });
  const moved = screen.getByRole('spinbutton', { name: 'Track number of track 3' });
  expect(moved.closest('details')).toBeNull();
  expect(moved).toHaveValue(9);
  expect(document.activeElement).toBe(moved);
});

test('a disabled table disables its inputs and the cleanup', () => {
  mount(pairingReview(), {}, true);
  for (const control of [...screen.getAllByRole('spinbutton'), screen.getByRole('checkbox')]) expect(control).toBeDisabled();
});
